/* Private planning prototype. Technical product specifications still require approval. */
'use strict';
const S=window.GestorSchedule;
const $=q=>document.querySelector(q);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h3m3 0h2m-8 3h3"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>',line:'<rect x="3" y="8" width="18" height="8" rx="2"/><path d="M6 8V4m6 4V4m6 4V4M6 16v4m6-4v4m6-4v4M7 12h10"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8m-8 4h6"/>',book:'<path d="M12 5c-3-2-7-2-10-1v16c4-1 7-1 10 1 3-2 6-2 10-1V4c-3-1-7-1-10 1v16"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6zM8 12l3 3 5-6"/>',alert:'<path d="m12 3 10 18H2zM12 9v4m0 4v.01"/>',pin:'<path d="m9 3 6 0-1 6 4 4v2H6v-2l4-4zM12 15v7"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',moon:'<path d="M20 14a9 9 0 0 1-10-11 9 9 0 1 0 10 11"/>',play:'<path d="m8 4 12 8-12 8z"/>',pause:'<path d="M9 5v14M15 5v14"/>',down:'<path d="M12 4v16m-6-6 6 6 6-6"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
const badge=(text,tone='')=>`<span class="badge ${tone}">${esc(text)}</span>`;
const avatar=name=>`<span class="avatar">${esc(name.slice(0,2).toUpperCase())}</span>`;
const linkButton=(href,text,primary=false,ico='arrow')=>`<a href="#${href}" class="button ${primary?'primary':''}">${esc(text)}${icon(ico)}</a>`;
const defaultProducts=[
 {id:'nacional-a',name:'Bolsa nacional · A',market:'Nacional',variation:'Subconjunto A — demonstrativo',fp:'FP a cadastrar',revision:'—'},
 {id:'nacional-b',name:'Bolsa nacional · B',market:'Nacional',variation:'Subconjunto B — demonstrativo',fp:'FP a cadastrar',revision:'—'},
 {id:'internacional-a',name:'Bolsa internacional · A',market:'Internacional',variation:'Subconjunto A — demonstrativo',fp:'FP a cadastrar',revision:'—'},
 {id:'internacional-b',name:'Bolsa internacional · B',market:'Internacional',variation:'Subconjunto B — demonstrativo',fp:'FP a cadastrar',revision:'—'}
];
const pages=[['overview','Visão geral','grid'],['schedule','Montagem de escala','calendar'],['employees','Funcionários','users'],['line','Linha de produção','line'],['fp','FP e produtos','file'],['guide','Orientações','book'],['settings','Configurações','shield']];
const sectors=['Sala de máquinas','Linha de bolsa','Subconjunto','Embalagem final'];
let config=S.defaults(), employees=[], result=null, viewIndex=0, theme='dark', query='',fpFocus='nacional-a',storageMode='loading',lastSaved='',saveTimer=null,saveQueue=Promise.resolve();
const STORAGE='gestor-subconjunto-v4';
try{localStorage.removeItem('gestor-subconjunto-v2');theme=localStorage.getItem('gestor-theme')==='light'?'light':'dark';}catch{}
const payload=()=>({config,employees,generated:!!result});
function storageStatus(message){const el=$('#storageStatus');if(el)el.textContent=message;}
function save(){
 if(storageMode==='loading')return;
 try{localStorage.setItem('gestor-theme',theme);}catch{}
 const data=JSON.stringify(payload());if(data===lastSaved)return;
 if(storageMode==='local'){
  try{localStorage.setItem(STORAGE,JSON.stringify({version:4,...payload()}));lastSaved=data;storageStatus('Rascunho local · banco SQL aguardando configuração.');}
  catch{storageStatus('Salvamento local indisponível.');}
  return;
 }
 clearTimeout(saveTimer);saveTimer=setTimeout(()=>{saveQueue=saveQueue.catch(()=>{}).then(async()=>{
  const latest=JSON.stringify(payload());if(latest===lastSaved)return;
  storageStatus('Salvando no banco SQL…');
  const response=await fetch('/api/state.js',{method:'PUT',headers:{'Content-Type':'application/json'},body:latest});
  if(!response.ok)throw new Error((await response.json().catch(()=>({}))).error||'Falha ao salvar.');
  lastSaved=latest;storageStatus('Dados salvos no banco SQL.');
 }).catch(error=>{storageStatus('Falha ao salvar no banco SQL.');notify(error.message);});},450);
}
async function loadState(){
 try{
  const response=await fetch('/api/state.js',{cache:'no-store'});
  if(!response.ok)throw new Error('Banco não configurado');
  const saved=await response.json();config={...S.defaults(),...saved.config};employees=saved.employees||[];
  if(saved.generated&&employees.length)result=buildResult();
  storageMode='sql';lastSaved=JSON.stringify(payload());storageStatus('Dados salvos no banco SQL.');
 }catch{
  try{const saved=JSON.parse(localStorage.getItem(STORAGE)||'null');if(saved?.version===4&&Array.isArray(saved.employees)){
   config={...config,...saved.config};employees=saved.employees;if(saved.generated&&employees.length)result=buildResult();
  }}catch{}
  storageMode='local';lastSaved=JSON.stringify(payload());storageStatus('Rascunho local · banco SQL aguardando configuração.');
 }
 render();
}
function invalidate(){result=null;viewIndex=0;save();}
const catalog=()=>Array.isArray(config.fps)?config.fps:defaultProducts;
const selected=()=>employees.filter(p=>p.active&&p.present&&(p.role||'Operador')==='Operador');
const assistants=()=>employees.filter(p=>p.active&&p.present&&p.role==='Assistente');
const organizers=()=>assistants().filter(p=>(config.organizerIds||[]).includes(p.id));
const extras=()=>Array.isArray(config.extraPosts)?config.extraPosts:[];
const product=()=>catalog().find(p=>p.id===config.product)||catalog()[0]||{id:'',name:'Nenhum produto cadastrado',market:'Nacional',variation:'',fp:'FP pendente',revision:'—'};
function buildResult(){
 const output=S.generate(config,employees);
 if(output.errors.length)return output;
 output.extraPosts=structuredClone(extras());
 output.organizers=organizers().map(p=>({id:p.id,name:p.name}));
 const blocks=output.rows.filter(r=>r.kind==='work');
 for(const post of output.extraPosts)if(!post.employeeId&&blocks.length)output.gaps.push({station:post.id,start:blocks[0].start,end:blocks.at(-1).end});
 output.complete=!output.gaps.length&&!output.warnings.length;
 return output;
}
function reconcileAssignments(){
 const live=new Map(employees.filter(p=>p.present&&p.active).map(p=>[p.id,p]));
 config.organizerIds=(config.organizerIds||[]).filter(id=>live.get(id)?.role==='Assistente');
 for(const post of extras()){const p=live.get(post.employeeId);if(!p||(p.role||'Operador')!=='Operador'||p.noGlue||p.fixed)post.employeeId='';}
}
const nameOf=(id,source=employees)=>source.find(p=>p.id===id)?.name||'Pendente';
function hintOf(p){return p.noGlue?'Sem cola · somente clampe':p.fixed?`Fixo · ${S.stations.find(s=>s.id===p.fixed)?.name}`:'Participa do rodízio';}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function heading(kicker,title,subtitle,action=''){return `<div class="page-heading"><div><p class="eyebrow">${esc(kicker)}</p><h1>${esc(title)}</h1><p class="subtitle">${esc(subtitle)}</p></div>${action}</div>`;}
function alertBox(text,tone=''){return `<div class="alert ${tone}">${icon(tone==='success'?'check':tone==='info'?'file':'alert')}<div>${text}</div></div>`;}
function metric(label,value,unit,foot,ico){return `<article class="metric"><span class="metric-icon">${icon(ico)}</span><div><span class="metric-label">${label}</span><strong>${value}<small>${unit}</small></strong><span class="metric-foot">${foot}</span></div></article>`;}
function videoMarkup(id,className=''){return `<div class="video-wrap ${className}"><video id="${id}" autoplay muted loop playsinline preload="metadata" poster="/assets/linha-poster.jpg" aria-label="Animação demonstrativa dos seis postos da linha de produção"><source src="/assets/linha-producao-corte.mp4" type="video/mp4"></video></div>`;}
function initVideos(){const observer='IntersectionObserver'in window?new IntersectionObserver(entries=>entries.forEach(entry=>{const box=entry.target.closest('.video-wrap');box?.classList.toggle('in-view',entry.isIntersecting);if(entry.isIntersecting)entry.target.play().catch(()=>{});}),{threshold:.25}):null;document.querySelectorAll('video').forEach(video=>{video.addEventListener('error',()=>notify('O vídeo não carregou. A imagem de prévia permanece disponível.'),{once:true});video.play().catch(()=>{});observer?.observe(video);});}

function intro(){
 $('#introScreen').innerHTML=`<div class="intro-grid" aria-hidden="true"></div><header class="intro-header"><a class="intro-brand" href="#intro"><span class="intro-logo">G<span>+</span></span><div>Gestor<small>DE SUBCONJUNTO</small></div></a><div class="intro-header-right"><span class="intro-private">${icon('shield')} AMBIENTE PRIVADO</span></div></header>
 <section class="intro-hero scroll-cinema"><div class="cinema-frame">${videoMarkup('introVideo','intro-video')}</div><button class="scroll-cue" data-action="scroll-entry">ROLE PARA ACESSAR ${icon('down')}</button></section>
 <section class="intro-entry" id="entrySection"><div class="entry-orbit" aria-hidden="true"></div><p class="intro-kicker">ACESSO AO PROTÓTIPO</p><h2>Entrar no Gestor<br>de Subconjunto</h2><p>Monte a escala da linha e acompanhe quem está disponível.</p><a class="enter-button" href="#schedule">Acessar o sistema ${icon('arrow')}</a><small class="entry-note">Ambiente privado · cadastro inicial vazio</small></section>
 <footer class="intro-footer"><span>GESTOR DE SUBCONJUNTO</span><p>Proposta independente para apresentação.</p><span>ACESSO PRIVADO</span></footer>`;
 initVideos();
}
function statusText(){return !result?'Escala precisa ser gerada':result.errors.length?'Configuração incompleta':result.complete?'Simulação sem lacunas':'Simulação com pendências';}
function displayRow(){if(result?.rows.length)return result.rows[Math.min(viewIndex,result.rows.length-1)];return null;}
function postStrip(){const row=displayRow();return S.stations.map((s,j)=>{const id=row?.assign[j],p=employees.find(p=>p.id===id),pause=row?.kind==='break';return `<button class="post-mini ${p?.noGlue?'restricted':''} ${!id&&!pause?'empty':''}" data-station="${s.id}" aria-label="Ver posto ${s.id}, ${esc(s.name)}"><span class="post-number">POSTO ${s.id}</span><strong>${s.name}</strong>${avatar(p?.name||'—')}<span class="person-name">${pause?'Intervalo':p?esc(p.name):result?'Pendente':'A definir'}</span>${p?.fixed?'<span class="fixed-mark">FIXO</span>':''}</button>`;}).join('');}
function overview(){
 const t=S.shift(config),p=product(),row=displayRow(),occupied=row?.assign.filter(Boolean).length||0;
 $('#app').innerHTML=heading('PAINEL DA OPERAÇÃO','Sua linha, em perspectiva.','Planejamento de subconjuntos · Uma linha, seis postos conectados.',linkButton('schedule','Montar escala',true,'plus'))+
 `<div class="metrics">${metric('Pessoas na equipe',selected().length,'pessoas','Selecionadas para este turno','users')}${metric('Postos cobertos',occupied,'/ 6',row?.kind==='break'?'Equipe em intervalo':'No horário visualizado','line')}${metric('Tempo efetivo',t.errors.length?'—':S.duration(t.workMinutes),'',`${esc(config.start)} — ${esc(config.end)}`,'clock')}${metric('Postos fixos',selected().filter(x=>x.fixed).length,'',`${selected().filter(x=>x.noGlue).length} restrição demonstrativa`,'shield')}</div>
 ${!result?alertBox('Você alterou a equipe ou a configuração. <a href="#schedule">Gere a escala para atualizar a distribuição.</a>','info'):result.errors.length?alertBox(esc(result.errors.join(' '))):result.gaps.length?alertBox(`<strong>Planejamento precisa de revisão.</strong> Há períodos sem cobertura. ${esc(result.warnings[0]||'Revise os postos fixos, a equipe e as restrições.')} <a href="#schedule">Ver escala →</a>`):''}
 <div class="overview-grid"><section class="card visual-card"><div class="card-head"><div><h2>Linha de produção</h2><p>${esc(p.name)} · ${esc(p.fp)}</p></div>${badge(row?.kind==='break'?'Em intervalo':'Simulação 3D')}</div><div class="line-toolbar"><div class="row"><span class="live-dot"></span> Uma linha · postos 20 a 70</div>${badge(statusText(),result?.complete?'green':'amber')}</div>${videoMarkup('dashboardVideo','dashboard-video')}<div class="illustration-caption">Animação ilustrativa. A distribuição válida para a simulação está nos cartões abaixo.</div><div class="post-strip" id="postStrip">${postStrip()}</div><div class="view-slider"><label for="timeSlider">Horário da escala</label><input type="range" id="timeSlider" min="0" max="${Math.max(0,(result?.rows.length||1)-1)}" value="${viewIndex}" ${result?.rows.length?'':'disabled'}><output id="timeOutput">${row?S.clock(row.start):config.start} — ${row?S.clock(row.end):config.end}</output></div><div class="view-foot"><span id="rowCaption">${row?.label||'Gere uma escala para visualizar os horários'}</span><a href="#line" class="text-button">Conhecer os postos ${icon('arrow')}</a></div></section>
 <aside class="aside-stack"><section class="card shift-card"><div class="section-label">Turno planejado ${badge('2º turno')}</div><div class="shift-time">${esc(config.start)}<span>→</span>${esc(config.end)}</div><div class="shift-caption">${dateLabel(config.date)} · ${t.errors.length?'Revise os horários':S.duration(t.workMinutes)+' de trabalho efetivo'}</div><div class="shift-timeline">${[[config.start,'Início do turno','Distribuição inicial'],[config.coffee,'Pausa para café',`${config.coffeeDuration} min · sem rodízio geral`],[config.lunch,'Intervalo de almoço',`${config.lunchDuration} min de intervalo`],[S.clock(t.breaks[1].end),'Retorno do almoço',config.rotation==='afterLunch'?'Primeira troca geral':'Rodízio a cada 2h efetivas'],[config.end,'Fim da jornada','Encerramento do planejamento']].map(([time,title,desc],i)=>`<div class="shift-event"><span class="event-dot ${i===0?'blue':''}"></span><time>${esc(time)}</time><div>${title}<p>${desc}</p></div></div>`).join('')}</div></section><section class="card rule-card"><h3>Regras que acompanham a equipe</h3><div class="rule-line">${icon('clock')} Preckoff: até 1h por pessoa</div><div class="rule-line">${icon('clock')} Contagem: até 2h por pessoa</div><div class="rule-line">${icon('pin')} Postos fixos respeitados</div><div class="rule-line">${icon('shield')} Sem retorno a posto já ocupado</div><a class="text-button" href="#guide">Entenda as regras ${icon('arrow')}</a></section></aside></div>
 <section class="card wide-card"><div class="card-head"><div><h2>Quem está na linha hoje</h2><p>Operadores ativos para o turno</p></div><a href="#employees" class="text-button">Gerenciar ${icon('arrow')}</a></div><div class="board-team">${selected().map(p=>`<div class="team-chip">${avatar(p.name)}<div>${esc(p.name)}<small>${esc(hintOf(p))}</small></div></div>`).join('')||'<p class="helper">Selecione os operadores presentes na montagem de escala.</p>'}</div><p class="helper organizer-summary"><strong>Organização da linha:</strong> ${organizers().length?organizers().map(p=>esc(p.name)).join(', '):'Assistente não selecionado'}</p></section>`;
 initVideos();
 $('#timeSlider').addEventListener('input',e=>{viewIndex=Number(e.target.value);$('#postStrip').innerHTML=postStrip();const r=displayRow();$('#timeOutput').textContent=`${S.clock(r.start)} — ${S.clock(r.end)}`;$('#rowCaption').textContent=r.label;const metricValues=document.querySelectorAll('.metric strong');metricValues[1].innerHTML=`${r.assign.filter(Boolean).length}<small>/ 6</small>`;});
}
function dateLabel(value){const d=new Date(value+'T12:00:00');return Number.isNaN(d.getTime())?'Data não definida':d.toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'});}
function options(values,selectedValue){return values.map(v=>`<option value="${esc(v.value)}" ${v.value===selectedValue?'selected':''}>${esc(v.label)}</option>`).join('');}
function schedule(){
 const p=product(),reserved=new Set(extras().map(x=>x.employeeId).filter(Boolean)),available=selected().filter(person=>!reserved.has(person.id));
 const stationSelect=s=>{const eligible=available.filter(person=>S.eligible(person,s));return `<article class="station-select ${eligible.length?'':'station-empty'}"><div><span class="station-index">${s.id}</span><span><b>${s.name}</b><small>${s.limit?`Troca a cada ${s.limit} min`:'Rodízio geral'}</small></span></div><label class="field"><span class="sr-only">Pessoa inicial no posto ${s.id}</span><select name="station-${s.id}" aria-label="Pessoa inicial no posto ${s.id}"><option value="">Distribuir automaticamente</option>${eligible.map(person=>`<option value="${esc(person.id)}" ${person.initial===s.id?'selected':''}>${esc(person.name)}${person.fixed===s.id?' · Fixo':''}</option>`).join('')}</select></label></article>`;};
 const extraRows=extras().map(x=>`<article class="station-select extra-select"><div><span class="station-index">${esc(x.id)}</span><span><b>${esc(x.name)}</b><small>Alocação manual · turno inteiro</small></span></div><label class="field"><span class="sr-only">Operador do posto adicional ${esc(x.id)}</span><select name="extra-${esc(x.id)}" aria-label="Operador do posto adicional ${esc(x.id)}">${options([{value:'',label:'Pendente · escolher operador'},...selected().filter(person=>!person.noGlue&&!person.fixed&&(!reserved.has(person.id)||person.id===x.employeeId)).map(person=>({value:person.id,label:person.name}))],x.employeeId||'')}</select></label><button type="button" class="button small" data-remove-extra="${esc(x.id)}" aria-label="Remover posto ${esc(x.id)}">Remover</button></article>`).join('');
 $('#app').innerHTML=heading('PLANEJAMENTO DO TURNO','Montagem de escala','Escolha o tipo de subconjunto e distribua a equipe pelos postos.',linkButton('overview','Visão geral',false,'grid'))+
 `<form id="scheduleForm" class="card schedule-form"><section class="form-section"><div class="form-section-heading"><span class="step">1</span><h3>Tipo de subconjunto</h3><span class="helper">Organizado por destino e variação</span></div><div class="form-grid three"><label class="field">Data<input type="date" name="date" value="${esc(config.date)}" required></label><label class="field">Destino<select name="market">${options(['Nacional','Internacional'].map(x=>({value:x,label:x})),p.market)}</select></label><label class="field">Variação<select name="product">${options(catalog().filter(x=>x.market===p.market).map(x=>({value:x.id,label:x.name})),p.id)}</select></label></div><div class="product-summary"><span>${badge(p.market,'green')}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.fp)} · revisão ${esc(p.revision)}</small></span><a href="#fp" class="text-button">Ver FPs ${icon('arrow')}</a></div>${!catalog().length?alertBox('Cadastre uma FP na página FP e produtos antes de gerar a escala.','info'):''}</section>
 <section class="form-section"><div class="form-section-heading"><span class="step">2</span><h3>Assistentes responsáveis</h3><span class="helper">${assistants().length} disponíveis</span></div><p class="helper form-copy">Selecione quem organiza a linha neste turno. Assistentes não ocupam os postos de operador.</p><div class="organizer-list">${assistants().map(person=>`<label class="check-field"><input type="checkbox" name="organizer" value="${esc(person.id)}" ${(config.organizerIds||[]).includes(person.id)?'checked':''}>${esc(person.name)} · ${esc(person.sector)}</label>`).join('')||'<p class="helper">Nenhum assistente ativo. Cadastre ou ative uma pessoa na categoria Assistente.</p>'}</div></section>
 <section class="form-section"><div class="form-section-heading"><span class="step">3</span><h3>Postos da linha</h3><span class="helper">${available.length} operadores disponíveis para o rodízio</span></div><p class="helper form-copy">Selecione quem começa em cada posto ou deixe em automático. O sistema mantém as restrições e mostra pendências quando faltar cobertura.</p><div class="station-selection">${S.stations.map(stationSelect).join('')}</div><div class="selection-toolbar"><a href="#employees" class="text-button">${icon('users')} Gerenciar disponibilidade dos funcionários</a></div></section>
 <section class="form-section"><div class="form-section-heading"><span class="step">4</span><h3>Outros postos</h3><span class="helper">${extras().length} adicionais</span></div><p class="helper form-copy">Cadastre postos de apoio para este turno e escolha um operador ativo para cada um. A alocação permanece durante o turno, exceto nos intervalos, e retira essa pessoa do rodízio 20–70.</p><div class="station-selection">${extraRows||'<p class="helper">Nenhum posto adicional neste turno.</p>'}</div><button type="button" class="button soft" data-action="add-extra">${icon('plus')} Adicionar outro posto</button></section>
 <details class="advanced-settings"><summary>Horários e rodízio da simulação</summary><div class="advanced-settings-body"><div class="form-grid three"><label class="field">Entrada<input type="time" name="start" value="${esc(config.start)}" required></label><label class="field">Saída<input type="time" name="end" value="${esc(config.end)}" required></label><label class="field">Rodízio geral<select name="rotation">${options([{value:'afterLunch',label:'Primeira troca após o almoço'},{value:'everyTwoHours',label:'A cada 2h trabalhadas desde a entrada'}],config.rotation)}</select></label></div><div class="break-settings"><label>Café<input type="time" name="coffee" value="${esc(config.coffee)}" aria-label="Início do café" required></label><label>Duração<input type="number" min="1" max="120" name="coffeeDuration" value="${esc(config.coffeeDuration)}" aria-label="Duração do café" required>min</label><label>Almoço<input type="time" name="lunch" value="${esc(config.lunch)}" aria-label="Início do almoço" required></label><label>Duração<input type="number" min="1" max="120" name="lunchDuration" value="${esc(config.lunchDuration)}" aria-label="Duração do almoço" required>min</label></div></div></details>
 <div class="generation-bar"><p><strong>Escala demonstrativa.</strong><br>A disponibilidade vem da tela Funcionários.</p><button type="submit" class="button primary" id="generateButton" ${catalog().length?'':'disabled'}>${icon('spark')} Gerar escala</button></div></form><div id="scheduleResult">${renderResult()}</div><div id="preckoffResult">${renderPreckoffPlan()}</div>`;
 $('#scheduleForm').addEventListener('change',e=>{const name=e.target.name;if(name==='market'){config.product=catalog().find(item=>item.market===e.target.value)?.id||'';invalidate();schedule();return;}if(name==='product'){config.product=e.target.value;invalidate();schedule();return;}if(name==='organizer'){config.organizerIds=[...e.currentTarget.querySelectorAll('[name=organizer]:checked')].map(x=>x.value);invalidate();schedule();return;}if(name.startsWith('extra-')){const post=extras().find(x=>x.id===name.slice(6));if(post){post.employeeId=e.target.value;const person=employees.find(x=>x.id===post.employeeId);if(person)person.initial='';invalidate();schedule();}return;}if(name.startsWith('station-')){const station=name.slice(8);employees.forEach(person=>{if(person.initial===station)person.initial='';});const person=employees.find(item=>item.id===e.target.value);if(person)person.initial=station;invalidate();schedule();return;}if(Object.hasOwn(config,name)){config[name]=name.endsWith('Duration')?Number(e.target.value):e.target.value;invalidate();$('#scheduleResult').innerHTML=renderResult();$('#preckoffResult').innerHTML=renderPreckoffPlan();}});
 $('#scheduleForm').addEventListener('submit',e=>{e.preventDefault();if(!catalog().some(x=>x.id===config.product)){notify('Cadastre e selecione uma FP antes de gerar a escala.');return;}const form=new FormData(e.currentTarget);for(const key of Object.keys(config))if(form.has(key))config[key]=key.endsWith('Duration')?Number(form.get(key)):form.get(key);result=buildResult();viewIndex=0;save();$('#scheduleResult').innerHTML=renderResult();$('#preckoffResult').innerHTML=renderPreckoffPlan();$('#scheduleResult').scrollIntoView({behavior:'smooth',block:'start'});notify(result.errors.length?'Revise a configuração antes de gerar a escala.':result.complete?'Escala gerada sem lacunas de cobertura.':'Escala gerada com pendências para revisão.');});
}
function renderPreckoffPlan(){
 if(!selected().length)return '';
 const plan=S.generatePreckoff(config,employees);
 if(plan.errors.length)return `<section class="result-section preckoff-plan"><div class="result-heading"><div><h2>Escala exclusiva · Preckoff</h2><p class="helper">Gere por hora após corrigir os horários do turno.</p></div></div>${alertBox(plan.errors.map(esc).join('<br>'))}</section>`;
 const row=plan.entries.map(entry=>{const person=plan.employees.find(p=>p.id===entry.personId);const when=entry.fragments.map(f=>`${S.clock(f.start)} — ${S.clock(f.end)}`).join(' + ');return `<tr><td>${entry.slot}</td><td>${when}<small>${entry.minutes} min efetivos</small></td><td class="${person?'changed':'gap'}">${person?esc(person.name):'Pendente'}${person?.supportPreckoff?'<small>apoio de preckoff</small>':''}</td></tr>`;}).join('');
 return `<section class="result-section preckoff-plan"><div class="result-heading"><div><h2>Escala exclusiva · Preckoff</h2><div class="result-meta">${badge('Troca a cada 1h','green')}<span>${plan.entries.length} ciclos</span><span>Restritos excluídos</span></div></div><div class="actions"><button class="button small" data-action="preckoff-print">${icon('download')} Gerar PDF do preckoff</button></div></div>${plan.warnings.length?alertBox(plan.warnings.map(esc).join('<br>')):alertBox('Lista horária criada somente com pessoas elegíveis para o posto 40.','success')}<div class="card"><div class="table-scroll"><table class="schedule-table preckoff-table"><thead><tr><th>CICLO</th><th>HORÁRIO</th><th>POSTO 40 · PRECKOFF</th></tr></thead><tbody>${row}</tbody></table></div></div></section>`;
}
function renderResult(){
 if(!result)return `<div class="result-section">${alertBox(employees.length?'Há alterações ainda não aplicadas. Clique em <strong>Gerar escala</strong> para calcular uma nova distribuição.':'Cadastre funcionários, marque quem está Ativo na linha e depois gere a escala.','info')}</div>`;
 if(result.errors.length)return `<section class="result-section">${alertBox(result.errors.map(esc).join('<br>'))}</section>`;
 const extraPosts=result.extraPosts||[],organizerNames=(result.organizers||[]).map(p=>p.name);
 let previous=[];
 const rows=result.rows.map(row=>{
  if(row.kind==='break')return `<tr class="break-row"><td class="time-cell">${S.clock(row.start)} — ${S.clock(row.end)}</td><td colspan="${6+extraPosts.length}">${row.label} · ${row.end-row.start} min · toda a equipe em intervalo</td></tr>`;
  const cells=row.assign.map((id,j)=>{const p=result.employees.find(x=>x.id===id);return `<td class="${!id?'gap':id!==previous[j]?'changed':''}">${id?esc(p?.name):'Pendente'}${p?.fixed?'<span class="fixed-mark"> · fixo</span>':''}${p?.noGlue?'<small>somente clampe</small>':''}</td>`;}).join('');previous=row.assign;
  const additional=extraPosts.map(post=>`<td class="${post.employeeId?'changed':'gap'}">${post.employeeId?esc(nameOf(post.employeeId,result.employees)):'Pendente'}<small>Alocação manual</small></td>`).join('');
  return `<tr><td class="time-cell">${S.clock(row.start)} — ${S.clock(row.end)}<small>${esc(row.label)} · ${row.end-row.start} min</small></td>${cells}${additional}</tr>`;
 }).join('');
 return `<section class="result-section"><div class="print-only">GESTOR DE SUBCONJUNTO · SIMULAÇÃO DEMONSTRATIVA · ${dateLabel(result.config.date)} · ${esc(catalog().find(p=>p.id===result.config.product)?.fp)} · ${esc(statusText())}</div><div class="result-heading"><div><h2>Escala do turno</h2><div class="result-meta">${badge(statusText(),result.complete?'green':'amber')}<span>${dateLabel(result.config.date)}</span><span>${S.duration(result.workMinutes)} efetivas</span></div></div><div class="actions"><button class="button small" data-action="csv">${icon('download')} Baixar CSV</button><button class="button small" data-action="print">${icon('download')} Gerar PDF</button></div></div>
 ${result.warnings.length?alertBox(result.warnings.map(esc).join('<br>')):result.gaps.length?alertBox('Não foi encontrada uma distribuição completa com estas regras. Revise a equipe e as fixações.'):alertBox('A simulação cobriu todos os postos respeitando as restrições cadastradas. Revise os dados com a liderança antes de qualquer uso operacional.','success')}
 <div class="card organizer-result"><strong>Organização da linha:</strong> ${organizerNames.length?organizerNames.map(esc).join(', '):'Nenhum assistente selecionado'}</div>
 <div class="card"><div class="table-scroll" tabindex="0" aria-label="Escala por horário e posto"><table class="schedule-table"><thead><tr><th>HORÁRIO</th>${S.stations.map(s=>`<th>${s.id} · ${s.name}</th>`).join('')}${extraPosts.map(s=>`<th>${esc(s.id)} · ${esc(s.name)}<small>Adicional</small></th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div><div class="export-note">Os horários consideram minutos efetivamente trabalhados. Azul marca mudança de pessoa. Os postos adicionais são manuais e não seguem o rodízio 20–70. Pausas não contam como saída do posto.</div></div>
 ${result.gaps.length?`<div class="card wide-card"><div class="card-head"><h3>Cobertura que precisa de revisão</h3>${badge(`${result.gaps.length} períodos`,'amber')}</div><ul class="alerts-list">${result.gaps.map(g=>`<li><strong>${S.clock(g.start)} — ${S.clock(g.end)} · ${esc(S.stations.find(s=>s.id===g.station)?.name||extraPosts.find(s=>s.id===g.station)?.name||g.station)}</strong><br>Sem pessoa atribuída. Adicione suplentes ou revise fixações e presenças; a restrição não foi flexibilizada.</li>`).join('')}</ul></div>`:''}</section>`;
}
